CREATE TABLE IF NOT EXISTS gis_phase372_boundary_datasets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), dataset_key TEXT NOT NULL UNIQUE, provider TEXT NOT NULL, source_url TEXT, source_version TEXT, hierarchy_level TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'DISCOVERED', feature_count BIGINT NOT NULL DEFAULT 0, valid_geometry_count BIGINT NOT NULL DEFAULT 0, state_count BIGINT NOT NULL DEFAULT 0, lga_count BIGINT NOT NULL DEFAULT 0, ward_count BIGINT NOT NULL DEFAULT 0, checksum TEXT, provenance JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), validated_at TIMESTAMPTZ); CREATE TABLE IF NOT EXISTS gis_phase372_boundary_features (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), dataset_id UUID NOT NULL REFERENCES gis_phase372_boundary_datasets(id) ON DELETE CASCADE, boundary_level TEXT NOT NULL, boundary_id TEXT NOT NULL, parent_id TEXT, name TEXT, state_code TEXT, geometry_geojson JSONB, geometry_valid BOOLEAN NOT NULL DEFAULT false, geometry_empty BOOLEAN NOT NULL DEFAULT true, properties JSONB NOT NULL DEFAULT '{}'::jsonb, UNIQUE(dataset_id,boundary_level,boundary_id)); CREATE TABLE IF NOT EXISTS gis_phase372_ingestion_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), dataset_key TEXT NOT NULL, status TEXT NOT NULL, features_loaded BIGINT NOT NULL DEFAULT 0, errors BIGINT NOT NULL DEFAULT 0, report JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());